//! D-Bus proxies for the op-openvswitch-daemon
//!
//! These zbus proxy types allow any crate in the workspace to call the
//! hypervisor daemon through D-Bus instead of directly linking rovs_ovsdb
//! or shelling out to ovs-vsctl / ovs-ofctl.
//!
//! Locked design (AGENTS.md §4):
//! - Daemon paths: `/org/opdbus/rovs/jsonrpc` and `/org/opdbus/rovs/openflow`
//! - Interfaces: `org.opdbus.rovs.jsonrpc` and `org.opdbus.rovs.openflow`
//! - The daemon is a pure passthrough; business logic stays in the plugins.

use anyhow::{Context, Result};
use std::sync::Arc;
use zbus::{proxy, Connection};

// ── RovsJsonRpcProxy ──────────────────────────────────────────────────────────

/// Proxy for the OVSDB JSON-RPC passthrough interface.
///
/// D-Bus destination: `org.opdbus.v1`
/// Object path: `/org/opdbus/rovs/jsonrpc`
/// Interface: `org.opdbus.rovs.jsonrpc`
#[proxy(
    default_service = "org.opdbus.v1",
    default_path = "/org/opdbus/rovs/jsonrpc",
    interface = "org.opdbus.rovs.jsonrpc"
)]
pub trait RovsJsonRpc {
    /// Execute a raw OVSDB JSON-RPC `transact`.
    ///
    /// `method` is the JSON-RPC method name (e.g. `"transact"`).
    /// `params_json` is the JSON-encoded parameter array.
    /// Returns the JSON-encoded result.
    async fn transact(&self, method: &str, params_json: &str) -> zbus::Result<String>;

    /// Execute a one-way OVSDB JSON-RPC `notify`.
    async fn notify(&self, method: &str, params_json: &str) -> zbus::Result<()>;

    /// Return the next JSON-RPC request id.
    async fn next_id(&self) -> zbus::Result<u64>;

    /// Send a raw JSON-RPC message string and return the response string.
    async fn send_message(&self, msg: &str) -> zbus::Result<String>;

    /// Receive a raw JSON-RPC message string.
    async fn recv_message(&self) -> zbus::Result<String>;

    /// Poll whether notification queue has pending items.
    async fn has_pending_notifications(&self) -> zbus::Result<bool>;

    /// Return the count of pending notifications.
    async fn pending_notification_count(&self) -> zbus::Result<u64>;

    /// Pop one notification from the queue as a JSON string.
    async fn pop_notification(&self) -> zbus::Result<String>;

    /// Drain all pending notifications as a JSON array string.
    async fn drain_notifications(&self) -> zbus::Result<String>;

    /// Open a new named stream / monitor.
    async fn new_stream(&self, stream: &str) -> zbus::Result<String>;

    /// Daemon status JSON.
    async fn status(&self) -> zbus::Result<String>;
}

/// Convenience constructor: build a `RovsJsonRpcProxy` on the system bus.
pub async fn jsonrpc_proxy() -> Result<RovsJsonRpcProxy<'static>> {
    let conn = Connection::system()
        .await
        .context("connect to system D-Bus for RovsJsonRpcProxy")?;
    Ok(RovsJsonRpcProxy::new(&conn).await?)
}

// ── RovsOpenFlowProxy ─────────────────────────────────────────────────────────

/// Proxy for the OpenFlow passthrough interface.
///
/// D-Bus destination: `org.opdbus.v1`
/// Object path: `/org/opdbus/rovs/openflow`
/// Interface: `org.opdbus.rovs.openflow`
#[proxy(
    default_service = "org.opdbus.v1",
    default_path = "/org/opdbus/rovs/openflow",
    interface = "org.opdbus.rovs.openflow"
)]
pub trait RovsOpenFlow {
    /// Connect to a switch at `addr` (e.g. `"tcp:127.0.0.1:6653"`).
    /// Returns connection handle id or error JSON.
    async fn connect(&self, addr: &str) -> zbus::Result<String>;

    /// Return negotiated OpenFlow version JSON.
    async fn version(&self) -> zbus::Result<String>;

    /// Send a flow_mod. `flow_json` is a JSON-encoded Flow struct.
    async fn send_flow(&self, flow_json: &str) -> zbus::Result<String>;

    /// Send a flow_mod and wait for barrier reply.
    async fn send_flow_sync(&self, flow_json: &str) -> zbus::Result<String>;

    /// Raw `ovs-ofctl` passthrough (temporary until pure OpenFlow binary is wired).
    /// `bridge` is the bridge name, `args_json` is a JSON array of extra CLI args.
    async fn ofctl(&self, bridge: &str, args_json: &str) -> zbus::Result<String>;

    /// Send an echo request, return echo reply JSON.
    async fn echo(&self) -> zbus::Result<String>;

    /// Send a barrier request, return barrier reply JSON.
    async fn barrier(&self) -> zbus::Result<String>;

    /// Dump all flows. Returns JSON array of FlowStatsEntry.
    async fn dump_flows(&self) -> zbus::Result<Vec<String>>;

    /// Dump flows matching a filter request JSON.
    async fn dump_flows_filtered(&self, request: &str) -> zbus::Result<Vec<String>>;

    /// Block until a PacketIn message arrives. Returns JSON PacketIn.
    async fn recv_packet_in(&self) -> zbus::Result<String>;

    /// Non-blocking try-receive PacketIn. Returns JSON or empty string.
    async fn try_recv_packet_in(&self) -> zbus::Result<String>;

    /// Start flow monitor with request JSON. Returns initial updates.
    async fn monitor_flows(&self, request: &str) -> zbus::Result<Vec<String>>;

    /// Block until flow updates arrive. Returns JSON array of FlowUpdate.
    async fn recv_flow_updates(&self) -> zbus::Result<Vec<String>>;

    /// Send a packet_out. `packet_out_json` is JSON-encoded PacketOut.
    async fn send_packet_out(&self, packet_out_json: &str) -> zbus::Result<String>;

    /// Controller status JSON.
    async fn status(&self) -> zbus::Result<String>;
}

/// Convenience constructor: build a `RovsOpenFlowProxy` on the system bus.
pub async fn openflow_proxy() -> Result<RovsOpenFlowProxy<'static>> {
    let conn = Connection::system()
        .await
        .context("connect to system D-Bus for RovsOpenFlowProxy")?;
    Ok(RovsOpenFlowProxy::new(&conn).await?)
}

// ── Unified helper ────────────────────────────────────────────────────────────

/// Ensure the op-openvswitch-daemon is reachable on D-Bus before proceeding.
///
/// This is the preferred entry-point for plugins: call this, then use the
/// returned proxies instead of `OvsdbClient` or `Command::new("ovs-vsctl")`.
pub async fn ensure_proxies() -> Result<(RovsJsonRpcProxy<'static>, RovsOpenFlowProxy<'static>)> {
    let json = jsonrpc_proxy().await?;
    let of = openflow_proxy().await?;
    Ok((json, of))
}

// ── OvsdbDbusClient ─────────────────────────────────────────────────────────

/// High-level OVSDB client that routes through the D-Bus daemon.
///
/// Mirrors the `OvsdbClient` API so plugin migrations are mechanical.
///
/// Construction is **synchronous** (like the original `OvsdbClient`) — the
/// underlying D-Bus connection is established lazily on the first async call.
/// This lets `StatePlugin::new()` stay sync.
#[derive(Clone)]
pub struct OvsdbDbusClient {
    proxy: Arc<tokio::sync::OnceCell<RovsJsonRpcProxy<'static>>>,
}

impl Default for OvsdbDbusClient {
    fn default() -> Self {
        Self::new()
    }
}

impl OvsdbDbusClient {
    /// Synchronous constructor — D-Bus connection is deferred until first use.
    pub fn new() -> Self {
        Self {
            proxy: Arc::new(tokio::sync::OnceCell::new()),
        }
    }

    /// Internal: get or create the proxy.
    async fn get_proxy(&self) -> Result<&RovsJsonRpcProxy<'static>> {
        self.proxy
            .get_or_try_init(|| async { jsonrpc_proxy().await })
            .await
            .context("connect to op-openvswitch-daemon via D-Bus")
    }

    // ── Internal: build & send a transact ───────────────────────────────

    async fn transact_one(&self, op: serde_json::Value) -> Result<serde_json::Value> {
        let proxy = self.get_proxy().await?;
        let params = serde_json::json!(["Open_vSwitch", op]);
        let raw = proxy
            .transact("transact", &params.to_string())
            .await
            .context("D-Bus transact call failed")?;
        let val: serde_json::Value = serde_json::from_str(&raw)
            .with_context(|| format!("daemon returned invalid JSON: {}", raw))?;
        Ok(val)
    }

    async fn transact_many(&self, ops: Vec<serde_json::Value>) -> Result<serde_json::Value> {
        let proxy = self.get_proxy().await?;
        let params = serde_json::json!(["Open_vSwitch", ops]);
        let raw = proxy
            .transact("transact", &params.to_string())
            .await
            .context("D-Bus transact call failed")?;
        let val: serde_json::Value = serde_json::from_str(&raw)
            .with_context(|| format!("daemon returned invalid JSON: {}", raw))?;
        Ok(val)
    }

    // ── Read helpers ──────────────────────────────────────────────────────

    /// Return `true` if the daemon (and OVSDB) is reachable.
    pub async fn list_dbs(&self) -> Result<Vec<String>> {
        let proxy = self.get_proxy().await?;
        let raw = proxy
            .transact("list_dbs", "[]")
            .await
            .context("list_dbs D-Bus call failed")?;
        let val: serde_json::Value = serde_json::from_str(&raw)?;
        Ok(val
            .as_array()
            .cloned()
            .unwrap_or_default()
            .iter()
            .filter_map(|v| v.as_str().map(String::from))
            .collect())
    }

    /// Return `true` if a bridge with the given name exists.
    pub async fn bridge_exists(&self, bridge_name: &str) -> Result<bool> {
        let result = self
            .transact_one(serde_json::json!({
                "op": "select",
                "table": "Bridge",
                "where": [["name", "==", bridge_name]],
                "columns": ["_uuid"]
            }))
            .await?;
        Ok(result
            .get("rows")
            .and_then(|r| r.as_array())
            .map(|a| !a.is_empty())
            .unwrap_or(false))
    }

    /// Return the names of all bridges.
    pub async fn list_bridges(&self) -> Result<Vec<String>> {
        let result = self
            .transact_one(serde_json::json!({
                "op": "select",
                "table": "Bridge",
                "where": [],
                "columns": ["name"]
            }))
            .await?;
        Ok(result
            .get("rows")
            .and_then(|r| r.as_array())
            .cloned()
            .unwrap_or_default()
            .iter()
            .filter_map(|r| r.get("name").and_then(|v| v.as_str()).map(String::from))
            .collect())
    }

    /// Return the names of all ports on a bridge.
    pub async fn list_bridge_ports(&self, bridge_name: &str) -> Result<Vec<String>> {
        let bridge_result = self
            .transact_one(serde_json::json!({
                "op": "select",
                "table": "Bridge",
                "where": [["name", "==", bridge_name]],
                "columns": ["ports"]
            }))
            .await?;
        let bridge_rows = bridge_result.get("rows").and_then(|r| r.as_array());
        let port_uuids: Vec<String> = match bridge_rows {
            Some(rows) if !rows.is_empty() => {
                let mut uuids = Vec::new();
                if let Some(ports) = rows[0].get("ports") {
                    Self::collect_uuids(ports, &mut uuids);
                }
                uuids
            }
            _ => return Ok(Vec::new()),
        };

        let mut names = Vec::new();
        for uuid in port_uuids {
            let result = self
                .transact_one(serde_json::json!({
                    "op": "select",
                    "table": "Port",
                    "where": [["_uuid", "==", ["uuid", uuid]]],
                    "columns": ["name"]
                }))
                .await?;
            if let Some(row) = result
                .get("rows")
                .and_then(|r| r.as_array())
                .and_then(|a| a.first())
            {
                if let Some(n) = row.get("name").and_then(|v| v.as_str()) {
                    names.push(n.to_string());
                }
            }
        }
        Ok(names)
    }

    /// Return the raw JSON row for a bridge.
    pub async fn get_bridge_info(&self, bridge_name: &str) -> Result<String> {
        let result = self
            .transact_one(serde_json::json!({
                "op": "select",
                "table": "Bridge",
                "where": [["name", "==", bridge_name]],
                "columns": []
            }))
            .await?;
        Ok(serde_json::to_string_pretty(&result)?)
    }

    // ── Mutation helpers ──────────────────────────────────────────────────

    /// Create a bridge if it does not exist.
    pub async fn create_bridge(&self, bridge_name: &str) -> Result<()> {
        if self.bridge_exists(bridge_name).await? {
            log::info!("Bridge {} already exists, skipping creation", bridge_name);
            return Ok(());
        }
        let ops = vec![
            serde_json::json!({
                "op": "insert",
                "table": "Bridge",
                "row": { "name": bridge_name, "stp_enable": false },
                "uuid-name": "new_bridge"
            }),
            serde_json::json!({
                "op": "mutate",
                "table": "Open_vSwitch",
                "where": [],
                "mutations": [["bridges", "insert", ["named-uuid", "new_bridge"]]]
            }),
        ];
        let result = self.transact_many(ops).await?;
        Self::check_errors(&result)?;
        log::info!("Bridge {} created via D-Bus daemon", bridge_name);
        Ok(())
    }

    /// Delete a bridge and its ports/interfaces.
    pub async fn delete_bridge(&self, bridge_name: &str) -> Result<()> {
        let bridge_result = self
            .transact_one(serde_json::json!({
                "op": "select",
                "table": "Bridge",
                "where": [["name", "==", bridge_name]],
                "columns": ["_uuid", "ports"]
            }))
            .await?;
        let bridge_rows = bridge_result.get("rows").and_then(|r| r.as_array());
        let (bridge_uuid, bridge_row) = match bridge_rows {
            Some(rows) if !rows.is_empty() => {
                let uuid = rows[0]
                    .get("_uuid")
                    .and_then(|u| u.as_array())
                    .and_then(|a| a.get(1))
                    .and_then(|v| v.as_str())
                    .map(String::from)
                    .ok_or_else(|| anyhow::anyhow!("bridge UUID not found"))?;
                (uuid, &rows[0])
            }
            _ => return Err(anyhow::anyhow!("Bridge '{}' not found", bridge_name)),
        };

        let mut port_uuids: Vec<String> = Vec::new();
        if let Some(ports) = bridge_row.get("ports") {
            Self::collect_uuids(ports, &mut port_uuids);
        }

        let mut iface_uuids: Vec<String> = Vec::new();
        for port_uuid in &port_uuids {
            let port_result = self
                .transact_one(serde_json::json!({
                    "op": "select",
                    "table": "Port",
                    "where": [["_uuid", "==", ["uuid", port_uuid.clone()]]],
                    "columns": ["interfaces"]
                }))
                .await?;
            if let Some(rows) = port_result.get("rows").and_then(|r| r.as_array()) {
                if let Some(row) = rows.first() {
                    if let Some(ifaces) = row.get("interfaces") {
                        Self::collect_uuids(ifaces, &mut iface_uuids);
                    }
                }
            }
        }

        let mut ops = vec![
            serde_json::json!({
                "op": "mutate",
                "table": "Open_vSwitch",
                "where": [],
                "mutations": [["bridges", "delete", ["uuid", bridge_uuid.clone()]]]
            }),
            serde_json::json!({
                "op": "delete",
                "table": "Bridge",
                "where": [["_uuid", "==", ["uuid", bridge_uuid]]]
            }),
        ];
        for port_uuid in &port_uuids {
            ops.push(serde_json::json!({
                "op": "delete",
                "table": "Port",
                "where": [["_uuid", "==", ["uuid", port_uuid]]]
            }));
        }
        for iface_uuid in &iface_uuids {
            ops.push(serde_json::json!({
                "op": "delete",
                "table": "Interface",
                "where": [["_uuid", "==", ["uuid", iface_uuid]]]
            }));
        }

        let result = self.transact_many(ops).await?;
        Self::check_errors(&result)?;
        log::info!("Bridge {} deleted via D-Bus daemon", bridge_name);
        Ok(())
    }

    /// Add a system port to a bridge.
    pub async fn add_port(&self, bridge_name: &str, port_name: &str) -> Result<()> {
        let ops = vec![
            serde_json::json!({
                "op": "insert",
                "table": "Interface",
                "row": { "name": port_name, "type": "system" },
                "uuid-name": "new_iface"
            }),
            serde_json::json!({
                "op": "insert",
                "table": "Port",
                "row": {
                    "name": port_name,
                    "interfaces": ["set", [["named-uuid", "new_iface"]]]
                },
                "uuid-name": "new_port"
            }),
            serde_json::json!({
                "op": "mutate",
                "table": "Bridge",
                "where": [["name", "==", bridge_name]],
                "mutations": [["ports", "insert", ["named-uuid", "new_port"]]]
            }),
        ];
        let result = self.transact_many(ops).await?;
        Self::check_errors(&result)?;
        log::info!(
            "Port {} added to bridge {} via D-Bus daemon",
            port_name,
            bridge_name
        );
        Ok(())
    }

    // ── Private helpers ───────────────────────────────────────────────────

    /// Recursively collect UUID strings from an OVSDB set value.
    fn collect_uuids(value: &serde_json::Value, out: &mut Vec<String>) {
        if let Some(arr) = value.as_array() {
            if arr.len() == 2 {
                if arr[0] == "uuid" {
                    if let Some(s) = arr[1].as_str() {
                        out.push(s.to_string());
                    }
                } else if arr[0] == "set" {
                    if let Some(items) = arr[1].as_array() {
                        for item in items {
                            Self::collect_uuids(item, out);
                        }
                    }
                }
            }
        }
    }

    /// Check a transact result for per-operation error objects.
    fn check_errors(result: &serde_json::Value) -> Result<()> {
        if let Some(results) = result.as_array() {
            for (i, op_result) in results.iter().enumerate() {
                if let Some(error) = op_result.get("error") {
                    if !error.is_null() {
                        let details = op_result
                            .get("details")
                            .and_then(|d| d.as_str())
                            .unwrap_or("no details");
                        return Err(anyhow::anyhow!(
                            "OVSDB operation {} failed: {} ({})",
                            i,
                            error,
                            details
                        ));
                    }
                }
            }
        }
        Ok(())
    }

    /// Set the `type` column on an Interface row (e.g. "internal", "system").
    pub async fn set_interface_type(&self, iface_name: &str, iface_type: &str) -> Result<()> {
        let ops = vec![serde_json::json!({
            "op": "update",
            "table": "Interface",
            "where": [["name", "==", iface_name]],
            "row": { "type": iface_type }
        })];
        let result = self.transact_many(ops).await?;
        Self::check_errors(&result)?;
        log::info!(
            "Interface {} type set to {} via D-Bus daemon",
            iface_name,
            iface_type
        );
        Ok(())
    }

    /// Set a bridge property (e.g., "datapath_type", "fail_mode").
    pub async fn set_bridge_property(
        &self,
        bridge_name: &str,
        property: &str,
        value: &str,
    ) -> Result<()> {
        let ops = vec![serde_json::json!({
            "op": "update",
            "table": "Bridge",
            "where": [["name", "==", bridge_name]],
            "row": { property: value }
        })];
        let result = self.transact_many(ops).await?;
        Self::check_errors(&result)?;
        log::info!(
            "Bridge {} property {} set to {} via D-Bus daemon",
            bridge_name,
            property,
            value
        );
        Ok(())
    }

    /// Delete a port from a bridge and remove associated Interface.
    pub async fn delete_port(&self, bridge_name: &str, port_name: &str) -> Result<()> {
        // First get the port UUID and its interface UUID
        let port_result = self
            .transact_one(serde_json::json!({
                "op": "select",
                "table": "Port",
                "where": [["name", "==", port_name]],
                "columns": ["_uuid", "interfaces"]
            }))
            .await?;

        let port_uuid = port_result
            .get("rows")
            .and_then(|r| r.as_array())
            .and_then(|a| a.first())
            .and_then(|row| row.get("_uuid"))
            .and_then(|u| u.as_array())
            .and_then(|a| a.get(1))
            .and_then(|u| u.as_str())
            .map(String::from)
            .ok_or_else(|| anyhow::anyhow!("Port '{}' not found", port_name))?;

        // Get interface UUIDs from port
        let mut iface_uuids: Vec<String> = Vec::new();
        if let Some(rows) = port_result.get("rows").and_then(|r| r.as_array()) {
            if let Some(row) = rows.first() {
                if let Some(ifaces) = row.get("interfaces") {
                    Self::collect_uuids(ifaces, &mut iface_uuids);
                }
            }
        }

        // Build delete operations: remove from bridge, delete port, delete interfaces
        let mut ops = vec![
            serde_json::json!({
                "op": "mutate",
                "table": "Bridge",
                "where": [["name", "==", bridge_name]],
                "mutations": [["ports", "delete", ["uuid", port_uuid.clone()]]]
            }),
            serde_json::json!({
                "op": "delete",
                "table": "Port",
                "where": [["_uuid", "==", ["uuid", port_uuid]]]
            }),
        ];

        for iface_uuid in iface_uuids {
            ops.push(serde_json::json!({
                "op": "delete",
                "table": "Interface",
                "where": [["_uuid", "==", ["uuid", iface_uuid]]]
            }));
        }

        let result = self.transact_many(ops).await?;
        Self::check_errors(&result)?;
        log::info!(
            "Port {} deleted from bridge {} via D-Bus daemon",
            port_name,
            bridge_name
        );
        Ok(())
    }

    /// Add a port with specific type to a bridge.
    pub async fn add_port_with_type(
        &self,
        bridge_name: &str,
        port_name: &str,
        port_type: Option<&str>,
    ) -> Result<()> {
        let ops = match port_type {
            Some(ptype) => vec![
                serde_json::json!({
                    "op": "insert",
                    "table": "Interface",
                    "row": { "name": port_name, "type": ptype },
                    "uuid-name": "new_iface"
                }),
                serde_json::json!({
                    "op": "insert",
                    "table": "Port",
                    "row": {
                        "name": port_name,
                        "interfaces": ["set", [["named-uuid", "new_iface"]]]
                    },
                    "uuid-name": "new_port"
                }),
                serde_json::json!({
                    "op": "mutate",
                    "table": "Bridge",
                    "where": [["name", "==", bridge_name]],
                    "mutations": [["ports", "insert", ["named-uuid", "new_port"]]]
                }),
            ],
            None => vec![
                serde_json::json!({
                    "op": "insert",
                    "table": "Interface",
                    "row": { "name": port_name },
                    "uuid-name": "new_iface"
                }),
                serde_json::json!({
                    "op": "insert",
                    "table": "Port",
                    "row": {
                        "name": port_name,
                        "interfaces": ["set", [["named-uuid", "new_iface"]]]
                    },
                    "uuid-name": "new_port"
                }),
                serde_json::json!({
                    "op": "mutate",
                    "table": "Bridge",
                    "where": [["name", "==", bridge_name]],
                    "mutations": [["ports", "insert", ["named-uuid", "new_port"]]]
                }),
            ],
        };

        let result = self.transact_many(ops).await?;
        Self::check_errors(&result)?;
        log::info!(
            "Port {} added to bridge {} via D-Bus daemon",
            port_name,
            bridge_name
        );
        Ok(())
    }

    /// Dump the contents of an OVSDB database as JSON.
    /// Returns a JSON object with database contents.
    pub async fn dump_db(&self, database: &str) -> Result<serde_json::Value> {
        // Query all tables in the database
        let tables_result = self
            .transact_one(serde_json::json!({
                "op": "select",
                "table": "Open_vSwitch",
                "where": [],
                "columns": []
            }))
            .await?;

        // Build a dump structure with all tables
        let mut dump = serde_json::json!({
            "database": database,
            "tables": {}
        });

        // Get list of tables from the database schema
        let schema_result = self
            .transact_one(serde_json::json!({
                "op": "get_schema",
                "id": "dump"
            }))
            .await?;

        if let Some(tables) = schema_result.get("tables").and_then(|t| t.as_object()) {
            for table_name in tables.keys() {
                let table_data = self
                    .transact_one(serde_json::json!({
                        "op": "select",
                        "table": table_name,
                        "where": [],
                        "columns": []
                    }))
                    .await?;

                if let Some(rows) = table_data.get("rows") {
                    dump["tables"][table_name] = rows.clone();
                }
            }
        }

        Ok(dump)
    }

    /// Monitor OVSDB for changes to a database.
    /// Returns a broadcast receiver that will receive JSON updates.
    /// NOTE: This is a compatibility shim. In the new architecture, use gRPC streaming
    /// (op-openvswitch-daemon/src/grpc_streaming.rs) for production monitoring.
    pub async fn monitor_db(
        &self,
        database: &str,
    ) -> Result<tokio::sync::broadcast::Receiver<serde_json::Value>> {
        let proxy = self.get_proxy().await?;
        // Create a stream/monitor subscription via D-Bus
        let _stream_id = proxy
            .new_stream(database)
            .await
            .map_err(|e| anyhow::anyhow!("Failed to create OVSDB monitor stream: {}", e))?;

        // Create a broadcast channel for updates
        // In a full implementation, this would be connected to the daemon's notification stream
        let (tx, rx) = tokio::sync::broadcast::channel(128);

        // Spawn a task that polls for notifications from the daemon
        let proxy_clone = self.proxy.clone();
        tokio::spawn(async move {
            loop {
                match proxy_clone.get() {
                    Some(proxy) => {
                        // Check if there are pending notifications
                        match proxy.has_pending_notifications().await {
                            Ok(true) => {
                                let drain_result: zbus::Result<String> =
                                    proxy.drain_notifications().await;
                                match drain_result {
                                    Ok(json_str) => {
                                        if let Ok(json) =
                                            serde_json::from_str::<serde_json::Value>(&json_str)
                                        {
                                            let _ = tx.send(json);
                                        }
                                    }
                                    Err(e) => {
                                        log::warn!("Failed to drain notifications: {}", e);
                                    }
                                }
                            }
                            Ok(false) => {
                                // No notifications pending, wait a bit
                                tokio::time::sleep(tokio::time::Duration::from_millis(100)).await;
                            }
                            Err(e) => {
                                log::warn!("Failed to check for pending notifications: {}", e);
                                tokio::time::sleep(tokio::time::Duration::from_millis(500)).await;
                            }
                        }
                    }
                    None => {
                        log::warn!("Proxy not available for monitoring");
                        tokio::time::sleep(tokio::time::Duration::from_millis(500)).await;
                    }
                }
            }
        });

        Ok(rx)
    }

    /// Compatibility shim for plugins that pass `simd_json::OwnedValue`.
    /// Converts to `serde_json::Value` and routes through the D-Bus daemon.
    pub async fn transact_simd(
        &self,
        operations: simd_json::OwnedValue,
    ) -> Result<serde_json::Value> {
        let text = simd_json::to_string(&operations)
            .context("failed to serialize simd_json operations to JSON text")?;
        let converted: serde_json::Value = serde_json::from_str(&text)
            .context("failed to deserialize simd_json operations as serde_json::Value")?;
        self.transact_many(converted.as_array().cloned().unwrap_or_default())
            .await
    }
}

//! Pure passthrough D-Bus interfaces for the op-openvswitch-daemon.
//!
//! TWO separate object paths (locked design):
//! - `/org/opdbus/rovs/jsonrpc`  → interface `org.opdbus.rovs.jsonrpc`
//! - `/org/opdbus/rovs/openflow` → interface `org.opdbus.rovs.openflow`
//!
//! The daemon knows NOTHING about bridges, ports, or containers.  It only
//! proxies raw `rovs-jsonrpc` / `rovs-openflow` primitives over D-Bus.
//! Business logic lives in the consuming plugins.

use anyhow::{Context, Result};
use rovs_ovsdb::Client;
use rovs_transport::Address;
use std::collections::HashMap;
use std::sync::Arc;
use tokio::sync::Mutex;
use tracing::{debug, info};
use zbus::interface;

// ── Shared daemon state ───────────────────────────────────────────────────────

/// Global state shared by both D-Bus objects.
#[derive(Clone)]
pub struct DaemonState {
    /// OVSDB JSON-RPC client (rovs_ovsdb).  Lazily initialised on first call.
    pub ovsdb: Arc<Mutex<Option<Client>>>,
    /// OVS Unix-domain socket path.
    pub socket_path: String,
    /// OpenFlow connections: conn_id → VConn.
    pub of_conns: Arc<Mutex<HashMap<u64, rovs_openflow::VConn>>>,
    /// Monotonic connection handle allocator.
    pub next_of_id: Arc<Mutex<u64>>,
}

impl DaemonState {
    pub fn new(socket_path: String) -> Self {
        Self {
            ovsdb: Arc::new(Mutex::new(None)),
            socket_path,
            of_conns: Arc::new(Mutex::new(HashMap::new())),
            next_of_id: Arc::new(Mutex::new(1)),
        }
    }

    /// Get or create the persistent OVSDB client.
    pub async fn get_ovsdb(&self) -> Result<tokio::sync::MutexGuard<'_, Option<Client>>> {
        let mut guard = self.ovsdb.lock().await;
        if guard.is_none() {
            let client = Client::connect(&format!("unix:{}", self.socket_path))
                .await
                .with_context(|| format!("connect to OVSDB at {}", self.socket_path))?;
            info!("OVSDB client connected to {}", self.socket_path);
            *guard = Some(client);
        }
        Ok(guard)
    }

    /// Allocate a new OpenFlow connection handle id.
    pub async fn alloc_of_id(&self) -> u64 {
        let mut n = self.next_of_id.lock().await;
        let id = *n;
        *n += 1;
        id
    }
}

// ── JSON-RPC object (/org/opdbus/rovs/jsonrpc) ──────────────────────────────

/// D-Bus service proxying raw `rovs-jsonrpc` + `rovs-ovsdb` primitives.
pub struct JsonRpcService {
    state: DaemonState,
}

impl JsonRpcService {
    pub fn new(state: DaemonState) -> Self {
        Self { state }
    }
}

#[interface(name = "org.opdbus.rovs.jsonrpc")]
impl JsonRpcService {
    /// Execute a raw OVSDB JSON-RPC `transact`.
    ///
    /// `method` — JSON-RPC method name (always `"transact"` for OVSDB).
    /// `params_json` — JSON-encoded params array (e.g. `["Open_vSwitch", {op:...}]`).
    /// Returns JSON-encoded result.
    async fn transact(&self, method: &str, params_json: &str) -> String {
        debug!(
            "jsonrpc.transact method={} params_len={}",
            method,
            params_json.len()
        );

        let mut guard = match self.state.get_ovsdb().await {
            Ok(g) => g,
            Err(e) => return json_error(&format!("OVSDB connect failed: {}", e)),
        };
        let client = match guard.as_mut() {
            Some(c) => c,
            None => return json_error("OVSDB client unavailable"),
        };

        // Parse params as serde_json::Value array.
        let params: serde_json::Value = match serde_json::from_str(params_json) {
            Ok(v) => v,
            Err(e) => return json_error(&format!("invalid params JSON: {}", e)),
        };

        // We use the rovs_ovsdb::Client::transact_raw or similar.
        // Since rovs_ovsdb::Client exposes `transact(Value) -> Result<Value>`,
        // we forward directly.
        match client.transact(params).await {
            Ok(result) => match serde_json::to_string(&result) {
                Ok(s) => s,
                Err(e) => json_error(&format!("serialize result failed: {}", e)),
            },
            Err(e) => json_error(&format!("transact failed: {}", e)),
        }
    }

    /// One-way notify (fire-and-forget).
    async fn notify(&self, _method: &str, _params_json: &str) {
        // rovs-jsonrpc notify support — placeholder; most callers use transact.
        debug!("jsonrpc.notify (passthrough stub)");
    }

    /// Return next JSON-RPC request id (monotonic counter).
    async fn next_id(&self) -> u64 {
        // Simplistic id counter.  In full rovs-jsonrpc this is per-connection.
        1
    }

    /// Send raw JSON-RPC message string, return response string.
    async fn send_message(&self, msg: &str) -> String {
        debug!("jsonrpc.send_message len={}", msg.len());
        match serde_json::from_str::<serde_json::Value>(msg) {
            Ok(req) => {
                let mut guard = match self.state.get_ovsdb().await {
                    Ok(g) => g,
                    Err(e) => return json_error(&format!("connect failed: {}", e)),
                };
                let client = match guard.as_mut() {
                    Some(c) => c,
                    None => return json_error("client unavailable"),
                };
                match client.transact(req).await {
                    Ok(r) => {
                        serde_json::to_string(&r).unwrap_or_else(|e| json_error(&e.to_string()))
                    }
                    Err(e) => json_error(&e.to_string()),
                }
            }
            Err(e) => json_error(&format!("invalid JSON: {}", e)),
        }
    }

    /// Receive raw JSON-RPC message string.
    async fn recv_message(&self) -> String {
        // rovs-jsonrpc recv is async-stream oriented; stub for now.
        String::new()
    }

    /// Poll pending notifications.
    async fn has_pending_notifications(&self) -> bool {
        false
    }

    /// Count pending notifications.
    async fn pending_notification_count(&self) -> u64 {
        0
    }

    /// Pop one notification.
    async fn pop_notification(&self) -> String {
        String::new()
    }

    /// Drain all notifications.
    async fn drain_notifications(&self) -> String {
        "[]".to_string()
    }

    /// Open a new named stream / monitor.
    async fn new_stream(&self, stream: &str) -> String {
        debug!("jsonrpc.new_stream stream={}", stream);
        format!("{{\"stream\":\"{}\"}}", stream)
    }

    /// Daemon + connection status JSON.
    async fn status(&self) -> String {
        let connected = self.state.ovsdb.lock().await.is_some();
        format!(
            "{{\"connected\":{},\"socket_path\":\"{}\",\"version\":\"{}\"}}",
            connected,
            self.state.socket_path,
            env!("CARGO_PKG_VERSION")
        )
    }
}

fn json_error(msg: &str) -> String {
    serde_json::json!({"error": msg}).to_string()
}

// ── OpenFlow object (/org/opdbus/rovs/openflow) ─────────────────────────────

/// D-Bus service proxying raw `rovs-openflow` primitives via `rovs_transport::Address`
/// and `rovs_openflow::VConn`.
pub struct OpenFlowService {
    state: DaemonState,
}

impl OpenFlowService {
    pub fn new(state: DaemonState) -> Self {
        Self { state }
    }
}

#[interface(name = "org.opdbus.rovs.openflow")]
impl OpenFlowService {
    /// Connect to a switch at `addr` (e.g. `"tcp:127.0.0.1:6653"`).
    ///
    /// `addr` is parsed by `rovs_transport::Address::from_str` which supports:
    /// - `unix:/path/to/socket`
    /// - `tcp:host:port`
    /// - `ssl:host:port`
    ///
    /// Returns JSON `{"conn_id":N}` or `{"error":"..."}`.
    async fn connect(&self, addr: &str) -> String {
        debug!("openflow.connect addr={}", addr);

        let address = match addr.parse::<Address>() {
            Ok(a) => a,
            Err(e) => return json_error(&format!("bad address: {}", e)),
        };

        match rovs_openflow::VConn::connect(&address).await {
            Ok(vconn) => {
                let id = self.state.alloc_of_id().await;
                self.state.of_conns.lock().await.insert(id, vconn);
                serde_json::json!({"conn_id": id}).to_string()
            }
            Err(e) => json_error(&format!("connect failed: {}", e)),
        }
    }

    /// Return negotiated OpenFlow version JSON.
    async fn version(&self, conn_id: u64) -> String {
        let mut conns = self.state.of_conns.lock().await;
        match conns.get_mut(&conn_id) {
            Some(vconn) => {
                let ver = vconn.version();
                serde_json::json!({"version": format!("{:?}", ver)}).to_string()
            }
            None => json_error("unknown conn_id"),
        }
    }

    async fn send_flow(&self, conn_id: u64, flow_json: &str) -> String {
        debug!(
            "openflow.send_flow conn_id={} len={}",
            conn_id,
            flow_json.len()
        );
        match parse_json_flow(flow_json) {
            Ok(rovs_flow) => {
                let mut conns = self.state.of_conns.lock().await;
                match conns.get_mut(&conn_id) {
                    Some(vconn) => match vconn.send_flow(&rovs_flow).await {
                        Ok(_) => serde_json::json!({"ok": true}).to_string(),
                        Err(e) => json_error(&format!("send_flow failed: {}", e)),
                    },
                    None => json_error("unknown conn_id"),
                }
            }
            Err(e) => json_error(&format!("JSON deserializer error: {}", e)),
        }
    }

    /// Send flow_mod + barrier.
    async fn send_flow_sync(&self, conn_id: u64, flow_json: &str) -> String {
        debug!("openflow.send_flow_sync conn_id={}", conn_id);
        match parse_json_flow(flow_json) {
            Ok(rovs_flow) => {
                let mut conns = self.state.of_conns.lock().await;
                match conns.get_mut(&conn_id) {
                    Some(vconn) => match vconn.send_flow_sync(&rovs_flow).await {
                        Ok(_) => serde_json::json!({"ok": true}).to_string(),
                        Err(e) => json_error(&format!("send_flow_sync failed: {}", e)),
                    },
                    None => json_error("unknown conn_id"),
                }
            }
            Err(e) => json_error(&format!("JSON deserializer error: {}", e)),
        }
    }

    /// Send an echo request and wait for the echo reply.
    async fn echo(&self, conn_id: u64) -> String {
        debug!("openflow.echo conn_id={}", conn_id);
        let mut conns = self.state.of_conns.lock().await;
        match conns.get_mut(&conn_id) {
            Some(vconn) => match vconn.echo().await {
                Ok(()) => serde_json::json!({"ok": true}).to_string(),
                Err(e) => json_error(&format!("echo failed: {}", e)),
            },
            None => json_error("unknown conn_id"),
        }
    }

    /// Send a barrier request and wait for the barrier reply.
    async fn barrier(&self, conn_id: u64) -> String {
        debug!("openflow.barrier conn_id={}", conn_id);
        let mut conns = self.state.of_conns.lock().await;
        match conns.get_mut(&conn_id) {
            Some(vconn) => match vconn.barrier().await {
                Ok(()) => serde_json::json!({"ok": true}).to_string(),
                Err(e) => json_error(&format!("barrier failed: {}", e)),
            },
            None => json_error("unknown conn_id"),
        }
    }

    /// Dump all flows from the switch.  Returns a JSON array string per flow.
    async fn dump_flows(&self, conn_id: u64) -> Vec<String> {
        debug!("openflow.dump_flows conn_id={}", conn_id);
        let mut conns = self.state.of_conns.lock().await;
        match conns.get_mut(&conn_id) {
            Some(vconn) => match vconn.dump_flows().await {
                Ok(entries) => entries.iter().map(flow_stats_to_json).collect(),
                Err(e) => vec![json_error(&format!("dump_flows failed: {}", e))],
            },
            None => vec![json_error("unknown conn_id")],
        }
    }

    /// Dump flows matching a filter.  `request_json` is a placeholder.
    async fn dump_flows_filtered(&self, conn_id: u64, _request: &str) -> Vec<String> {
        debug!("openflow.dump_flows_filtered conn_id={}", conn_id);
        // TODO: deserialize FlowStatsRequest from JSON, then call vconn.dump_flows_filtered(req)
        self.dump_flows(conn_id).await
    }

    /// Block until a PacketIn message arrives.
    /// Returns JSON with buffer_id, in_port, reason, table_id, cookie, data (hex).
    async fn recv_packet_in(&self, conn_id: u64) -> String {
        debug!("openflow.recv_packet_in conn_id={}", conn_id);
        let mut conns = self.state.of_conns.lock().await;
        match conns.get_mut(&conn_id) {
            Some(vconn) => match vconn.recv_packet_in().await {
                Ok(pkt) => packet_in_to_json(&pkt),
                Err(e) => json_error(&format!("recv_packet_in failed: {}", e)),
            },
            None => json_error("unknown conn_id"),
        }
    }

    /// Non-blocking try-receive PacketIn.
    async fn try_recv_packet_in(&self, conn_id: u64) -> String {
        let mut conns = self.state.of_conns.lock().await;
        match conns.get_mut(&conn_id) {
            Some(vconn) => match vconn.try_recv_packet_in().await {
                Ok(Some(pkt)) => packet_in_to_json(&pkt),
                Ok(None) => String::new(),
                Err(e) => json_error(&format!("try_recv_packet_in failed: {}", e)),
            },
            None => json_error("unknown conn_id"),
        }
    }

    /// Start flow monitor.  `request_json` is a placeholder.
    async fn monitor_flows(&self, conn_id: u64, _request: &str) -> Vec<String> {
        debug!("openflow.monitor_flows conn_id={}", conn_id);
        // TODO: deserialize FlowMonitorRequest from JSON
        Vec::new()
    }

    /// Block until flow updates arrive.
    async fn recv_flow_updates(&self, conn_id: u64) -> Vec<String> {
        debug!("openflow.recv_flow_updates conn_id={}", conn_id);
        let mut conns = self.state.of_conns.lock().await;
        match conns.get_mut(&conn_id) {
            Some(vconn) => match vconn.recv_flow_updates().await {
                Ok(updates) => updates.iter().map(flow_update_to_json).collect(),
                Err(e) => vec![json_error(&format!("recv_flow_updates failed: {}", e))],
            },
            None => vec![json_error("unknown conn_id")],
        }
    }

    /// Send a packet_out.  `packet_out_json` is a placeholder.
    async fn send_packet_out(&self, conn_id: u64, _packet_out_json: &str) -> String {
        debug!("openflow.send_packet_out conn_id={}", conn_id);
        // TODO: deserialize PacketOut from JSON
        let mut conns = self.state.of_conns.lock().await;
        match conns.get_mut(&conn_id) {
            Some(_vconn) => {
                json_error("send_packet_out: JSON→PacketOut deserialiser not yet implemented")
            }
            None => json_error("unknown conn_id"),
        }
    }

    /// Controller status JSON.
    async fn status(&self) -> String {
        let count = self.state.of_conns.lock().await.len();
        format!(
            "{{\"connections\":{},\"version\":\"{}\"}}",
            count,
            env!("CARGO_PKG_VERSION")
        )
    }
}

// ── JSON serializers for rovs-openflow types ──────────────────────────────────

fn flow_stats_to_json(entry: &rovs_openflow::FlowStatsEntry) -> String {
    serde_json::json!({
        "table_id": entry.table_id,
        "duration_sec": entry.duration_sec,
        "duration_nsec": entry.duration_nsec,
        "priority": entry.priority,
        "idle_timeout": entry.idle_timeout,
        "hard_timeout": entry.hard_timeout,
        "flags": entry.flags,
        "cookie": entry.cookie,
        "packet_count": entry.packet_count,
        "byte_count": entry.byte_count,
        "match_fields_hex": bytes_to_hex(&entry.match_fields.encode()),
        "instructions_hex": bytes_to_hex(&entry.instructions),
    })
    .to_string()
}

fn packet_in_to_json(pkt: &rovs_openflow::PacketIn) -> String {
    serde_json::json!({
        "buffer_id": pkt.buffer_id,
        "total_len": pkt.total_len,
        "reason": format!("{:?}", pkt.reason),
        "table_id": pkt.table_id,
        "cookie": pkt.cookie,
        "match_fields_hex": bytes_to_hex(&pkt.match_fields.encode()),
        "data_hex": bytes_to_hex(&pkt.data),
    })
    .to_string()
}

fn flow_update_to_json(update: &rovs_openflow::FlowUpdate) -> String {
    match update {
        rovs_openflow::FlowUpdate::Full(full) => serde_json::json!({
            "type": "Full",
            "event": format!("{:?}", full.event),
            "reason": full.reason,
            "priority": full.priority,
            "idle_timeout": full.idle_timeout,
            "hard_timeout": full.hard_timeout,
            "table_id": full.table_id,
            "cookie": full.cookie,
            "match_fields_hex": bytes_to_hex(&full.match_fields.encode()),
            "actions_hex": bytes_to_hex(&full.actions),
        }),
        rovs_openflow::FlowUpdate::Abbrev { xid } => serde_json::json!({
            "type": "Abbrev",
            "xid": xid,
        }),
    }
    .to_string()
}

/// Simple hex encoder (avoids pulling in the `hex` crate).
fn bytes_to_hex(bytes: &[u8]) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut s = String::with_capacity(bytes.len() * 2);
    for b in bytes {
        s.push(HEX[(b >> 4) as usize] as char);
        s.push(HEX[(b & 0xF) as usize] as char);
    }
    s
}

#[derive(serde::Deserialize, Debug)]
pub struct JsonFlowEntry {
    pub table: u8,
    pub priority: u16,
    pub match_fields: std::collections::HashMap<String, String>,
    pub actions: Vec<JsonFlowAction>,
    pub cookie: Option<u64>,
    #[serde(default)]
    pub idle_timeout: u16,
    #[serde(default)]
    pub hard_timeout: u16,
}

#[derive(serde::Deserialize, Debug)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum JsonFlowAction {
    Output { port: String },
    LoadRegister { register: u8, value: u64 },
    Resubmit { table: u8 },
    SetField { field: String, value: String },
    Drop,
    Normal,
    Controller { max_len: Option<u16> },
    ArpResponder { mac: String, ip: String },
}

fn parse_json_flow(flow_json: &str) -> Result<rovs_openflow::Flow> {
    let entry: JsonFlowEntry =
        serde_json::from_str(flow_json).context("invalid JsonFlowEntry format")?;

    let mut m = rovs_openflow::Match::new();
    for (k, v) in entry.match_fields {
        match k.as_str() {
            "in_port" => {
                if let Ok(port) = v.parse::<u32>() {
                    m = m.in_port(port);
                }
            }
            "dl_type" => {
                let eth_type = if v.starts_with("0x") {
                    u16::from_str_radix(v.trim_start_matches("0x"), 16).unwrap_or(0)
                } else {
                    v.parse().unwrap_or(0)
                };
                m = m.eth_type(eth_type);
            }
            "dl_vlan" => {
                if let Ok(vlan) = v.parse::<u16>() {
                    m = m.vlan_vid(vlan);
                }
            }
            // Add other matches here as required
            _ => {
                tracing::warn!("Unsupported match field in JSON->Flow map: {}={}", k, v);
            }
        }
    }

    let mut action_list = rovs_openflow::ActionList::new();
    for action in entry.actions {
        match action {
            JsonFlowAction::Output { port } => {
                if port.eq_ignore_ascii_case("LOCAL") {
                    action_list = action_list.output(rovs_openflow::OutputPort::Local);
                } else if port.eq_ignore_ascii_case("NORMAL") {
                    action_list = action_list.output(rovs_openflow::OutputPort::Normal);
                } else if let Ok(p) = port.parse::<u32>() {
                    action_list = action_list.output(rovs_openflow::OutputPort::Port(p));
                } else {
                    tracing::warn!("Invalid numeric port output: {}", port);
                }
            }
            JsonFlowAction::Normal => {
                action_list = action_list.output(rovs_openflow::OutputPort::Normal);
            }
            JsonFlowAction::Drop => {}
            // Other actions could be mapped here.
            _ => {
                tracing::warn!("Unsupported JSON->Flow action: {:?}", action);
            }
        }
    }

    let mut flow = rovs_openflow::Flow::add()
        .priority(entry.priority)
        .match_fields(m)
        .actions(action_list)
        .idle_timeout(entry.idle_timeout)
        .hard_timeout(entry.hard_timeout);

    if let Some(c) = entry.cookie {
        flow = flow.cookie(c);
    }

    // Some rovs_openflow Flow builders support .table_id(u8), we will skip it for now
    // unless explicitly supported by the FlowAddBuilder. (Usually table_id=0 by default).

    Ok(flow)
}

//! op-openvswitch-daemon — Pure passthrough D-Bus proxy for rovs primitives.
//!
//! TWO separate D-Bus object paths (locked design):
//! - `/org/opdbus/rovs/jsonrpc`  → `org.opdbus.rovs.jsonrpc`
//! - `/org/opdbus/rovs/openflow` → `org.opdbus.rovs.openflow`
//!
//! The daemon is a literal passthrough: it owns the rovs crate connections
//! and exposes raw primitives over D-Bus.  Zero business logic.
//!
//! Per AGENTS.md §4: D-Bus is the ONLY control plane.

use anyhow::{Context, Result};
use std::path::Path;
use tracing::{info, warn};
use zbus::connection::Connection;

mod dbus;
mod execution;
mod grpc;
mod grpc_streaming;

use dbus::{DaemonState, JsonRpcService, OpenFlowService};
use execution::PluginExecutionService;
use grpc_streaming::{EventBus, StreamingService};

// ── CLI ───────────────────────────────────────────────────────────────────────

#[derive(Debug, Clone)]
struct Args {
    grpc_addr: Option<String>,
    ovs_socket: Option<String>,
}

impl Args {
    fn parse() -> Self {
        let args: Vec<String> = std::env::args().collect();
        let mut grpc_addr = None;
        let mut ovs_socket = None;
        let mut i = 1;
        while i < args.len() {
            match args[i].as_str() {
                "--grpc" => {
                    if i + 1 < args.len() {
                        grpc_addr = Some(args[i + 1].clone());
                        i += 2;
                    } else {
                        i += 1;
                    }
                }
                "--ovs-socket" => {
                    if i + 1 < args.len() {
                        ovs_socket = Some(args[i + 1].clone());
                        i += 2;
                    } else {
                        i += 1;
                    }
                }
                _ => i += 1,
            }
        }
        Self {
            grpc_addr,
            ovs_socket,
        }
    }
}

// ── Socket discovery ────────────────────────────────────────────────────────

const DEFAULT_OVS_SOCKET: &str = "/var/run/openvswitch/db.sock";
const OVS_SOCKET_PATHS: &[&str] = &["/run/openvswitch/db.sock", "/var/run/openvswitch/db.sock"];

fn find_ovs_socket() -> String {
    OVS_SOCKET_PATHS
        .iter()
        .find(|p| Path::new(p).exists())
        .unwrap_or(&DEFAULT_OVS_SOCKET)
        .to_string()
}

// ── Main ────────────────────────────────────────────────────────────────────

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(tracing_subscriber::EnvFilter::from_default_env())
        .init();

    info!("Starting op-openvswitch-daemon (pure passthrough)");

    let args = Args::parse();
    let socket_path = args.ovs_socket.unwrap_or_else(find_ovs_socket);
    info!("Using OVS socket: {}", socket_path);

    let state = DaemonState::new(socket_path);

    // Eager-connect OVSDB so early callers don't wait.
    if let Err(e) = state.get_ovsdb().await {
        warn!(
            "Could not connect to OVSDB: {}. Will retry on first request.",
            e
        );
    }

    let conn = Connection::system()
        .await
        .context("Failed to connect to system D-Bus")?;
    info!("Connected to system D-Bus");

    // Register TWO separate object paths (locked design).
    let grpc_state = state.clone();
    let json_service = JsonRpcService::new(state.clone());
    let of_service = OpenFlowService::new(state);

    conn.object_server()
        .at("/org/opdbus/rovs/jsonrpc", json_service)
        .await
        .context("Failed to register /org/opdbus/rovs/jsonrpc")?;

    conn.object_server()
        .at("/org/opdbus/rovs/openflow", of_service)
        .await
        .context("Failed to register /org/opdbus/rovs/openflow")?;

    let exec_service = PluginExecutionService::new();
    conn.object_server()
        .at("/org/opdbus/execution", exec_service)
        .await
        .context("Failed to register /org/opdbus/execution")?;

    // Request single well-known bus name.
    conn.request_name("org.opdbus.v1")
        .await
        .context("Failed to request bus name org.opdbus.v1")?;

    info!("D-Bus services registered:");
    info!("  /org/opdbus/rovs/jsonrpc  -> org.opdbus.rovs.jsonrpc");
    info!("  /org/opdbus/rovs/openflow -> org.opdbus.rovs.openflow");
    info!("  /org/opdbus/execution     -> org.opdbus.execution");

    // Optional gRPC with streaming support (M2)
    if let Some(grpc_addr) = args.grpc_addr {
        let addr: std::net::SocketAddr = grpc_addr.parse().context("Invalid --grpc address")?;
        info!("Starting gRPC server on {}", addr);

        // Create shared event bus for streaming subscriptions
        let event_bus = EventBus::new();
        let streaming_service = StreamingService::new(grpc_state.clone(), event_bus);

        tokio::spawn(async move {
            if let Err(e) =
                grpc::run_grpc_server_with_streaming(addr, grpc_state, streaming_service).await
            {
                warn!("gRPC server error: {}", e);
            }
        });
    }

    info!("Daemon ready — Ctrl+C to stop");
    loop {
        tokio::time::sleep(tokio::time::Duration::from_secs(60)).await;
    }
}

//! OVSDB event feed integration
//!
//! Uses `OvsdbDbusClient::monitor_db()` which delivers full IDL snapshots (no
//! extra network connections) via `rovs_ovsdb::Client::wait()`.  The first
//! message received is the initial snapshot taken right after the monitoring
//! connection is established; subsequent messages arrive on every DB change.

use anyhow::Result;
use op_network::rovs_proxy::OvsdbDbusClient;
use std::sync::Arc;
use tokio::sync::broadcast;
use tracing::info;

use crate::event::MirrorEvent;

/// Spawn OVSDB monitor and send events to the broadcast channel.
///
/// The monitor uses the IDL-based snapshot format from `monitor_db()`:
/// `{ "TableName": [{ "_uuid": ["uuid", "..."], col: val, … }, …], … }`.
/// Each snapshot is exploded into individual `MirrorEvent::OvsdbRow` events —
/// one per row, per table.
pub async fn spawn_ovsdb_monitor(
    ovsdb: Arc<OvsdbDbusClient>,
    broadcast_tx: broadcast::Sender<MirrorEvent>,
) -> Result<()> {
    info!("Spawning OVSDB monitor for event feed");

    // monitor_db() returns a channel that delivers IDL snapshots.  The first
    // snapshot (sent immediately after connect) acts as the initial data load;
    // no separate dump_db() call is needed.
    let mut rx = ovsdb.monitor_db("Open_vSwitch").await?;

    tokio::spawn(async move {
        let mut sequence: u64 = 0;

        loop {
            match rx.recv().await {
                Ok(snapshot) => {
                    sequence = sequence.wrapping_add(1);

                    // snapshot = { "TableName": [ row, … ], … }
                    // Each row has "_uuid": ["uuid", "…"] plus column values.
                    let tables = match snapshot.as_object() {
                        Some(t) => t,
                        None => {
                            tracing::warn!("monitor_db: received non-object snapshot, skipping");
                            continue;
                        }
                    };

                    for (table_name, rows_val) in tables {
                        let rows = match rows_val.as_array() {
                            Some(r) => r,
                            None => continue,
                        };

                        for row in rows {
                            let uuid = extract_uuid(row);
                            let event = MirrorEvent::OvsdbRow {
                                table_name: table_name.clone(),
                                uuid,
                                delta: row.clone(),
                                sequence,
                            };
                            // A send error means all receivers dropped; the task keeps
                            // running so the monitoring connection stays alive.
                            let _ = broadcast_tx.send(event);
                        }
                    }
                }
                Err(tokio::sync::broadcast::error::RecvError::Lagged(n)) => {
                    tracing::warn!("OVSDB monitor_db subscription lagged by {} events", n);
                    continue;
                }
                Err(tokio::sync::broadcast::error::RecvError::Closed) => {
                    tracing::info!("OVSDB monitor_db channel closed, stopping event feed");
                    break;
                }
            }
        }
    });

    Ok(())
}

fn extract_uuid(row: &serde_json::Value) -> String {
    // Canonical OVSDB wire form: ["uuid", "<uuid-str>"]
    if let Some(uuid_val) = row.get("_uuid") {
        if let Some(uuid_arr) = uuid_val.as_array() {
            if uuid_arr.len() == 2 && uuid_arr[0].as_str() == Some("uuid") {
                if let Some(uuid_str) = uuid_arr[1].as_str() {
                    return uuid_str.to_string();
                }
            }
        }
    }
    // Fallback keys used by some callers
    if let Some(uuid) = row.get("uuid").and_then(|v| v.as_str()) {
        return uuid.to_string();
    }
    if let Some(id) = row.get("id").and_then(|v| v.as_str()) {
        return id.to_string();
    }
    if let Some(s) = row.get("name").and_then(|v| v.as_str()) {
        return s.to_string();
    }
    "unknown".to_string()
}

//! OVSDB Bridge plugin — 1:1 mirror of RFC 7047 Bridge/Port/Interface tables.
//!
//! OVSDB *is* the source of truth. This plugin queries reality from ovsdb-server
//! and projects it onto D-Bus via the mirror reconciliation loop. There is no
//! desired-vs-current diff — the database is the desired state.

use anyhow::Result;
use async_trait::async_trait;
use op_network::rovs_proxy::OvsdbDbusClient;
use op_state::{ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateDiff, StatePlugin};
use serde::{Deserialize, Serialize};
use simd_json::prelude::*;
use simd_json::OwnedValue as Value;
use std::sync::Arc;

// ============================================================================
// RFC 7047 §3.2 Schema Types — Bridge → Port → Interface hierarchy
// ============================================================================

/// Full OVS state — 1:1 projection of what ovsdb-server reports.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct OvsBridgeState {
    pub bridges: Vec<BridgeConfig>,
}

/// RFC 7047 Bridge table row.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct BridgeConfig {
    pub name: String,
    #[serde(default)]
    pub ports: Vec<PortConfig>,
    /// "system" | "netdev" | "" (kernel datapath)
    #[serde(default)]
    pub datapath_type: String,
    /// "standalone" | "secure" | null
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub fail_mode: Option<String>,
    #[serde(default)]
    pub stp_enable: bool,
    #[serde(default)]
    pub mcast_snooping_enable: bool,
    #[serde(default, skip_serializing_if = "std::collections::HashMap::is_empty")]
    pub other_config: std::collections::HashMap<String, String>,
}

/// RFC 7047 Port table row.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PortConfig {
    pub name: String,
    #[serde(default)]
    pub interfaces: Vec<InterfaceConfig>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub tag: Option<u16>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub trunks: Vec<u16>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub vlan_mode: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub bond_mode: Option<String>,
}

/// RFC 7047 Interface table row.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct InterfaceConfig {
    pub name: String,
    /// "system" | "internal" | "patch" | "vxlan" | "gre" | "geneve" | ""
    #[serde(default, rename = "type")]
    pub iface_type: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub mac_in_use: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub mac: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub admin_state: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub link_state: Option<String>,
    #[serde(default, skip_serializing_if = "std::collections::HashMap::is_empty")]
    pub options: std::collections::HashMap<String, String>,
}

// ============================================================================
// Plugin
// ============================================================================

pub struct OvsBridgePlugin {
    ovsdb: Arc<OvsdbDbusClient>,
}

impl Default for OvsBridgePlugin {
    fn default() -> Self {
        Self::new()
    }
}

impl OvsBridgePlugin {
    pub fn new() -> Self {
        Self {
            ovsdb: Arc::new(OvsdbDbusClient::new()),
        }
    }

    /// Query full Bridge→Port→Interface hierarchy from OVSDB.
    async fn query_bridges(&self) -> Result<OvsBridgeState> {
        let bridge_names = self.ovsdb.list_bridges().await.unwrap_or_default();
        let mut bridges = Vec::new();

        for bname in bridge_names {
            // Bridge-level properties
            let bridge_info = self.ovsdb.get_bridge_info(&bname).await.ok();
            let (datapath_type, fail_mode, stp_enable, mcast_snooping_enable) =
                Self::parse_bridge_props(&bridge_info);

            // Ports
            let port_names = self
                .ovsdb
                .list_bridge_ports(&bname)
                .await
                .unwrap_or_default();
            let ports: Vec<PortConfig> = port_names
                .into_iter()
                .map(|pname| PortConfig {
                    interfaces: vec![InterfaceConfig {
                        name: pname.clone(),
                        iface_type: String::new(),
                        mac_in_use: None,
                        mac: None,
                        admin_state: None,
                        link_state: None,
                        options: Default::default(),
                    }],
                    name: pname,
                    tag: None,
                    trunks: vec![],
                    vlan_mode: None,
                    bond_mode: None,
                })
                .collect();

            bridges.push(BridgeConfig {
                name: bname,
                ports,
                datapath_type,
                fail_mode,
                stp_enable,
                mcast_snooping_enable,
                other_config: Default::default(),
            });
        }

        Ok(OvsBridgeState { bridges })
    }

    fn parse_bridge_props(info: &Option<String>) -> (String, Option<String>, bool, bool) {
        let Some(ref info_str) = info else {
            return (String::new(), None, false, false);
        };
        let v: std::result::Result<Value, _> = serde_json::from_str(info_str);
        match v {
            Ok(row) => (
                row.get("datapath_type")
                    .and_then(|v| v.as_str())
                    .unwrap_or("")
                    .to_string(),
                row.get("fail_mode")
                    .and_then(|v| v.as_str())
                    .filter(|s| !s.is_empty())
                    .map(|s| s.to_string()),
                row.get("stp_enable")
                    .and_then(|v| v.as_bool())
                    .unwrap_or(false),
                row.get("mcast_snooping_enable")
                    .and_then(|v| v.as_bool())
                    .unwrap_or(false),
            ),
            Err(_) => (String::new(), None, false, false),
        }
    }
}

#[async_trait]
impl StatePlugin for OvsBridgePlugin {
    fn name(&self) -> &str {
        "ovsdb_bridge"
    }

    fn version(&self) -> &str {
        "1.0.0"
    }

    fn schema(&self) -> Option<op_state_store::PluginSchema> {
        Some(super::plugin_schema_defs::ovsdb_bridge_plugin_schema())
    }

    fn is_available(&self) -> bool {
        std::path::Path::new("/var/run/openvswitch/db.sock").exists()
    }

    fn unavailable_reason(&self) -> String {
        "OVSDB socket not found at /var/run/openvswitch/db.sock".to_string()
    }

    /// Query reality — dump OVSDB Bridge/Port/Interface tables.
    async fn query_current_state(&self) -> Result<Value> {
        let state = self.query_bridges().await?;
        Ok(simd_json::serde::to_owned_value(state)?)
    }

    /// Reconciliation, not diff. OVSDB is the DB — the "desired" parameter
    /// is what the D-Bus mirror currently shows. We return actions needed
    /// to update the mirror to match OVSDB reality.
    async fn calculate_diff(&self, _current: &Value, _desired: &Value) -> Result<StateDiff> {
        // No diff — OVSDB is authoritative. The mirror reconciliation loop
        // in op-dbus-mirror handles projection. Return empty diff.
        Ok(StateDiff {
            plugin: self.name().to_string(),
            actions: vec![],
            metadata: DiffMetadata {
                timestamp: chrono::Utc::now().timestamp(),
                current_hash: String::new(),
                desired_hash: String::new(),
            },
        })
    }

    /// No-op — reconciliation happens via the mirror, not through apply.
    async fn apply_state(&self, _diff: &StateDiff) -> Result<ApplyResult> {
        Ok(ApplyResult {
            success: true,
            changes_applied: vec![],
            errors: vec![],
            checkpoint: None,
        })
    }

    /// Verify just re-queries OVSDB — it's always "correct" by definition.
    async fn verify_state(&self, _desired: &Value) -> Result<bool> {
        Ok(true)
    }

    async fn create_checkpoint(&self) -> Result<Checkpoint> {
        let state = self.query_current_state().await?;
        Ok(Checkpoint {
            id: uuid::Uuid::new_v4().to_string(),
            plugin: self.name().to_string(),
            timestamp: chrono::Utc::now().timestamp(),
            state_snapshot: state,
            backend_checkpoint: None,
        })
    }

    async fn rollback(&self, _checkpoint: &Checkpoint) -> Result<()> {
        Ok(())
    }

    fn capabilities(&self) -> PluginCapabilities {
        PluginCapabilities {
            supports_rollback: false,
            supports_checkpoints: true,
            supports_verification: true,
            atomic_operations: true,
        }
    }
}

